"""Pydantic v2 schemas for Structured Output and Multi-Agent Tracing (REQ-15, REQ-17, Capabilities C & E)."""

from typing import List, Literal, Optional
from pydantic import BaseModel, Field, field_validator


class TicketCopilotStructuredOutput(BaseModel):
    """Structured triage and resolution pre-fill generated by LLM Copilot (Capability C)."""

    category: Literal["Authentication", "Billing", "Bug Report", "Feature Request", "General"] = "General"
    priority: Literal["Low", "Medium", "High", "Urgent"] = "Medium"
    ai_tags: List[str] = Field(min_length=1, max_length=5, description="1 to 5 automated tags")
    sentiment: Literal["positive", "neutral", "frustrated", "urgent"] = "neutral"
    summary: str = Field(min_length=10, max_length=300, description="Concise issue summary")
    ai_draft_reply: str = Field(min_length=20, description="Vietnamese localized resolution draft")

    @field_validator("category", mode="before")
    @classmethod
    def normalize_category_alias(cls, v: str) -> str:
        """Normalizes legacy 'Technical Bug' alias to canonical 'Bug Report'."""
        if not v:
            return "General"
        v_clean = str(v).strip()
        if v_clean == "Technical Bug":
            return "Bug Report"
        allowed = {"Authentication", "Billing", "Bug Report", "Feature Request", "General"}
        if v_clean in allowed:
            return v_clean
        return "General"

    @field_validator("priority", mode="before")
    @classmethod
    def normalize_priority(cls, v: str) -> str:
        """Normalizes priority level to canonical values."""
        if not v:
            return "Medium"
        v_clean = str(v).strip().capitalize()
        if v_clean in {"Low", "Medium", "High", "Urgent"}:
            return v_clean
        return "Medium"

    @field_validator("sentiment", mode="before")
    @classmethod
    def normalize_sentiment(cls, v: str) -> str:
        """Normalizes sentiment label."""
        if not v:
            return "neutral"
        v_clean = str(v).strip().lower()
        if v_clean in {"positive", "neutral", "frustrated", "urgent"}:
            return v_clean
        return "neutral"


class FaithfulnessJudgeStructuredOutput(BaseModel):
    """Structured evaluation judgment from FaithfulnessJudgeAgent (Capability C)."""

    score: float = Field(ge=0.0, le=1.0, description="Faithfulness confidence score from 0.0 to 1.0")
    status: Literal["passed", "warning", "failed"] = "passed"
    reason: str = Field(default="Câu trả lời bám sát nội dung tài liệu gốc.")
    missing_facts: List[str] = Field(default_factory=list)

    @field_validator("status", mode="before")
    @classmethod
    def normalize_status(cls, v: str) -> str:
        if not v:
            return "passed"
        v_low = str(v).strip().lower()
        if v_low in {"passed", "warning", "failed"}:
            return v_low
        return "warning"


class SyntheticQAPair(BaseModel):
    """Single synthetic question and ground truth pair."""

    question: str = Field(min_length=5)
    ground_truth: str = Field(min_length=5)


class SyntheticQAListStructuredOutput(BaseModel):
    """Structured list of synthetic QA pairs generated by SyntheticQAExamAgent."""

    items: List[SyntheticQAPair] = Field(default_factory=list)


class AgentHandOffStep(BaseModel):
    """Telemetry record for multi-agent hand-offs (Capability E - REQ-17)."""

    step_order: int = 1
    agent: Optional[str] = None
    from_agent: str
    to_agent: str
    action: str
    input_summary: str
    output_summary: str
    latency_ms: float
    status: Literal["success", "failed", "skipped"] = "success"
    timestamp: Optional[str] = None
